#include <stdio.h>
#include <string.h>

#define MAX 100

typedef struct {
    char name[32];
    char phone[20];
} Contact;

int add_one(Contact book[], int n, char *name, char *phone) {
    if (n >= MAX) {
        printf("记满了喵\n");
        return n;
    }
    strcpy(book[n].name, name);
    strcpy(book[n].phone, phone);
    return n + 1;
}

void list_all(Contact book[], int n) {
    if (n == 0) {
        printf("还一条都没有喵\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        printf("%d. %s %s\n", i + 1, book[i].name, book[i].phone);
    }
}

int main(void) {
    Contact book[MAX];
    int n = 0;

    n = add_one(book, n, "小橘", "{tel1}");
    n = add_one(book, n, "狸花", "{tel2}");

    printf("一共 %d 条\n", n);
    list_all(book, n);
    return 0;
}
